import {on} from 'delegated-events'
import {getBaseFetchHeaders} from '@github-ui/fetch-headers'

on('submit', '#account-redemption-lookup', event => {
  const form = event.currentTarget as HTMLFormElement
  const input = form.querySelector<HTMLInputElement>('input[type=text]')!
  form.action = encodeURI(`/biztools/${input.value}/billing/redemptions`)
})

on('submit', '#account-opensource-lookup', event => {
  const form = event.currentTarget as HTMLFormElement
  const input = form.querySelector<HTMLInputElement>('input[type=text]')!
  form.action = encodeURI(`/biztools/${input.value}/opensource`)
})

interface TradeControlsScreeningStatus {
  screened: boolean
}

export async function checkTradeControlsScreeningStatus(
  path: string,
  accountId: string,
): Promise<TradeControlsScreeningStatus> {
  try {
    const response = await fetch(`/biztools/trade_screening/status_check/${path}/${accountId}`, {
      headers: {
        ...getBaseFetchHeaders(),
      },
    })
    return response.json()
  } catch {
    return {screened: true}
  }
}

export function showNotScreenedWarningDialog(onProceed: () => void) {
  const dialog = document.getElementById('not-screened-warning-dialog') as HTMLDialogElement
  dialog.showModal()

  const proceedButton = dialog.querySelector('#proceed-without-screening')!
  const cancelButton = dialog.querySelector('#cancel')!

  const closeDialog = () => {
    proceedButton.removeEventListener('click', onProceedClick)
    cancelButton.removeEventListener('click', onCancelClick)
    dialog.close()
  }

  const onProceedClick = () => {
    closeDialog()
    onProceed()
  }

  const onCancelClick = () => {
    closeDialog()
  }

  proceedButton.addEventListener('click', onProceedClick)
  cancelButton.addEventListener('click', onCancelClick)
}

export async function handleFormSubmit(event: Event, inputName: string, path: string) {
  event.preventDefault()
  const form = event.currentTarget as HTMLFormElement
  const input = form.querySelector<HTMLInputElement>(`input[name=${inputName}]`)!
  const jsonBody = await checkTradeControlsScreeningStatus(path, input.value)

  if (jsonBody.screened) {
    form.submit()
  } else {
    showNotScreenedWarningDialog(() => {
      form.submit()
    })
  }
}

on('submit', '#js-apply-coupon-to-account-form', event => {
  handleFormSubmit(event, 'user_id', 'by_user_id')
})

on('submit', '#js-apply-coupon-to-enterprise-account-form', event => {
  handleFormSubmit(event, 'slug', 'by_slug')
})

function toggleCouponFields() {
  const box = document.querySelector<HTMLInputElement>('#js-coupon-unique-codes #bulk_generate_coupons')
  if (!box) return

  const quantity = document.querySelector<HTMLElement>('.js-coupon-quantity')!
  const prefix = document.querySelector<HTMLElement>('.js-coupon-prefix')!
  const code = document.querySelector<HTMLElement>('.js-coupon-code')!
  const limit = document.querySelector<HTMLElement>('.js-coupon-limit')!

  if (box.checked) {
    quantity.hidden = false
    prefix.hidden = false
    limit.hidden = true
    code.hidden = true
  } else {
    quantity.hidden = true
    prefix.hidden = true
    limit.hidden = false
    code.hidden = false
  }
}

on('change', '#js-coupon-unique-codes #bulk_generate_coupons', () => {
  toggleCouponFields()
})

// Run on page load
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', toggleCouponFields)
} else {
  toggleCouponFields()
}
